def trace(grid):
    a=[r[:] for r in grid]; H=len(a); W=len(a[0])
    sr,sc=next((r,c) for r in range(H) for c in range(W) if a[r][c]==2)
    h_adj=sum(a[r][c]==8 and a[r][c+1]==8 for r in range(H) for c in range(W-1))
    v_adj=sum(a[r][c]==8 and a[r+1][c]==8 for r in range(H-1) for c in range(W))
    # axis (the direction of travel) and perpendicular coordinate
    if h_adj >= v_adj:
        axis='row'; step=1 if sr < H//2 else -1; cur=sr; active={sc}
        def get(t,p): return a[t][p]
        def set2(t,p):
            if a[t][p]!=8: a[t][p]=2
        def lane(t,L,R):
            q=t-step
            if 0<=q<H:
                for p in range(max(0,L-1),min(W-1,R+1)+1):
                    set2(q,p)
        def endpoints(t,L,R): return [p for p in (L-1,R+1) if 0<=p<W and a[t][p]!=8]
        maxaxis=H; maxperp=W
    else:
        axis='col'; step=1 if sc < W//2 else -1; cur=sc; active={sr}
        def get(t,p): return a[p][t]
        def set2(t,p):
            if a[p][t]!=8: a[p][t]=2
        def lane(t,L,R):
            q=t-step
            if 0<=q<W:
                for p in range(max(0,L-1),min(H-1,R+1)+1): set2(q,p)
        def endpoints(t,L,R): return [p for p in (L-1,R+1) if 0<=p<H and a[p][t]!=8]
        maxaxis=W; maxperp=H
    # traverse from source along axis
    if axis=='row':
        cur=sr; active={sc}
    else: cur=sc; active={sr}
    while 0<=cur<maxaxis and active:
        new=set()
        for p in sorted(active):
            if get(cur,p)==8:
                L=R=p
                while L>0 and get(cur,L-1)==8: L-=1
                while R<maxperp-1 and get(cur,R+1)==8: R+=1
                lane(cur,L,R)
                outs=endpoints(cur,L,R)
                for q in outs:
                    set2(cur,q); new.add(q)
            else:
                set2(cur,p); new.add(p)
        active=new
        cur+=step
    return a
